fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // If the coefficient grid is exactly 1×1, return its sole entry;
    // otherwise return 0.0.
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Check preconditions
    let n = x.len();
    assert!(n > 0, "Input arrays must have positive length");
    assert!(
        y.len() == n,
        "The two input arrays must have the same length"
    );
    assert!(!c.is_empty(), "Coefficient grid must be non-empty");
    for row in &c {
        assert!(!row.is_empty(), "Each row in the coefficient grid must be non-empty");
    }

    // Compute the default value and fill the result
    let v = default_value(&c);
    vec![v; n]
}

